package com.osu.michja56.backend.config;

import com.osu.michja56.backend.model.Product;
import com.osu.michja56.backend.model.User; // Nový import
import com.osu.michja56.backend.repository.ProductRepository;
import com.osu.michja56.backend.repository.UserRepository; // Nový import
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.math.BigDecimal;
import java.util.List;

@Configuration
public class DataInitializer {

    @Bean
    CommandLineRunner initDatabase(ProductRepository productRepo, UserRepository userRepo) {
        return args -> {
            // --- INICIALIZACE PRODUKTŮ ---
            if (productRepo.count() == 0) {
                Product p1 = new Product();
                p1.setName("Herní Notebook");
                p1.setPrice(new BigDecimal("25000.00"));
                p1.setImageUrl("https://placehold.co/400x400?text=Notebook");

                Product p2 = new Product();
                p2.setName("Mechanická klávesnice");
                p2.setPrice(new BigDecimal("1800.00"));
                p2.setImageUrl("https://placehold.co/400x400?text=Klavesnice");

                productRepo.saveAll(List.of(p1, p2));
                System.out.println(">> Produkty vloženy.");
            }

            // --- INICIALIZACE UŽIVATELŮ ---
            if (userRepo.count() == 0) {
                // Admin
                User admin = new User();
                admin.setUsername("admin");
                admin.setPassword("admin123");
                admin.setEmail("admin@eshop.cz");
                admin.setRole("ADMIN");
                userRepo.save(admin);

                // Běžný uživatel
                User user = new User();
                user.setUsername("pepa");
                user.setPassword("pepa123");
                user.setEmail("pepa@email.cz");
                user.setRole("USER");
                userRepo.save(user);

                System.out.println(">> Testovací uživatelé vytvořeni (admin/admin123, pepa/pepa123).");
            }
        };
    }
}

package com.osu.michja56.backend.config;

import com.osu.michja56.backend.model.Product;
import com.osu.michja56.backend.model.User; // Nový import
import com.osu.michja56.backend.repository.ProductRepository;
import com.osu.michja56.backend.repository.UserRepository; // Nový import
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;

import java.math.BigDecimal;
import java.util.List;

@Configuration
public class DataInitializer {

    @Bean
    CommandLineRunner initDatabase(ProductRepository productRepo, UserRepository userRepo) {
        return args -> {
            // --- INICIALIZACE PRODUKTŮ ---
            if (productRepo.count() == 0) {
                Product p1 = new Product();
                p1.setName("Herní Notebook");
                p1.setPrice(new BigDecimal("25000.00"));
                p1.setImageUrl("https://placehold.co/400x400?text=Notebook");

                Product p2 = new Product();
                p2.setName("Mechanická klávesnice");
                p2.setPrice(new BigDecimal("1800.00"));
                p2.setImageUrl("https://placehold.co/400x400?text=Klavesnice");

                productRepo.saveAll(List.of(p1, p2));
                System.out.println(">> Produkty vloženy.");
            }

            // --- INICIALIZACE UŽIVATELŮ ---
            if (userRepo.count() == 0) {
                BCryptPasswordEncoder passwordEncoder = new BCryptPasswordEncoder();
                // Admin
                User admin = new User();
                admin.setUsername("admin");
                admin.setPassword(passwordEncoder.encode("admin123"));
                admin.setEmail("admin@eshop.cz");
                admin.setRole("ADMIN");
                userRepo.save(admin);

                // Běžný uživatel
                User user = new User();
                user.setUsername("pepa");
                user.setPassword(passwordEncoder.encode("pepa123"));
                user.setEmail("pepa@email.cz");
                user.setRole("USER");
                userRepo.save(user);

                System.out.println(">> Testovací uživatelé vytvořeni (admin/admin123, pepa/pepa123).");
            }
        };
    }
}

package com.osu.michja56.backend.controller;

import com.osu.michja56.backend.model.User;
import com.osu.michja56.backend.repository.UserRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Optional;

@RestController
@RequestMapping("/api/auth")
@CrossOrigin(origins = "http://localhost:5173")
public class AuthController {

    private final UserRepository userRepository;

    public AuthController(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody User loginData) {
        Optional<User> user = userRepository.findByUsername(loginData.getUsername());

        if (user.isPresent() && user.get().getPassword().equals(loginData.getPassword())) {
            return ResponseEntity.ok(user.get());
        }

        return ResponseEntity.status(401).body("Neplatné jméno nebo heslo");
    }
}

package com.osu.michja56.backend.controller;

import com.osu.michja56.backend.dto.LoginRequest;
import com.osu.michja56.backend.dto.RegisterRequest;
import com.osu.michja56.backend.dto.UserResponse;
import com.osu.michja56.backend.model.User;
import com.osu.michja56.backend.repository.UserRepository;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.util.StringUtils;
import org.springframework.web.bind.annotation.*;

import java.util.Optional;

@RestController
@RequestMapping("/api/auth")
@CrossOrigin(origins = "http://localhost:5173")
public class AuthController {

    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder = new BCryptPasswordEncoder();

    public AuthController(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest loginData) {
        Optional<User> user = userRepository.findByUsername(loginData.getUsername());

        if (user.isPresent() && passwordMatches(user.get(), loginData.getPassword())) {
            return ResponseEntity.ok(UserResponse.from(user.get()));
        }

        return ResponseEntity.status(401).body("Neplatné jméno nebo heslo");
    }

    @PostMapping("/register")
    public ResponseEntity<?> register(@RequestBody RegisterRequest registerData) {
        if (!StringUtils.hasText(registerData.getUsername())
                || !StringUtils.hasText(registerData.getPassword())
                || !StringUtils.hasText(registerData.getEmail())) {
            return ResponseEntity.badRequest().body("Vyplňte uživatelské jméno, e-mail a heslo.");
        }

        if (userRepository.findByUsername(registerData.getUsername()).isPresent()) {
            return ResponseEntity.status(HttpStatus.CONFLICT).body("Uživatelské jméno už existuje.");
        }

        if (userRepository.findByEmail(registerData.getEmail()).isPresent()) {
            return ResponseEntity.status(HttpStatus.CONFLICT).body("E-mail už existuje.");
        }

        User user = new User();
        user.setUsername(registerData.getUsername().trim());
        user.setPassword(passwordEncoder.encode(registerData.getPassword()));
        user.setEmail(registerData.getEmail().trim());
        user.setFirstName(trimToNull(registerData.getFirstName()));
        user.setLastName(trimToNull(registerData.getLastName()));
        user.setRole("USER");

        User saved = userRepository.save(user);
        return ResponseEntity.status(HttpStatus.CREATED).body(UserResponse.from(saved));
    }

    private boolean passwordMatches(User user, String rawPassword) {
        String stored = user.getPassword();
        if (stored == null || rawPassword == null) {
            return false;
        }

        boolean matches = isBcryptHash(stored)
                ? passwordEncoder.matches(rawPassword, stored)
                : stored.equals(rawPassword);

        if (matches && !isBcryptHash(stored)) {
            user.setPassword(passwordEncoder.encode(rawPassword));
            userRepository.save(user);
        }

        return matches;
    }

    private boolean isBcryptHash(String value) {
        return value.startsWith("$2a$") || value.startsWith("$2b$") || value.startsWith("$2y$");
    }

    private String trimToNull(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }
}

package com.osu.michja56.backend.dto;

import lombok.Data;

@Data
public class LoginRequest {

    private String username;
    private String password;
}

package com.osu.michja56.backend.dto;

import lombok.Data;

@Data
public class RegisterRequest {

    private String username;
    private String password;
    private String email;
    private String firstName;
    private String lastName;
}

package com.osu.michja56.backend.dto;

import com.osu.michja56.backend.model.User;
import lombok.Data;

@Data
public class UserResponse {

    private Long id;
    private String username;
    private String email;
    private String firstName;
    private String lastName;
    private String role;

    public static UserResponse from(User user) {
        UserResponse response = new UserResponse();
        response.setId(user.getId());
        response.setUsername(user.getUsername());
        response.setEmail(user.getEmail());
        response.setFirstName(user.getFirstName());
        response.setLastName(user.getLastName());
        response.setRole(user.getRole());
        return response;
    }
}

import React, { useState } from 'react';
import axios from 'axios';

const Login = ({ onLoginSuccess }) => {
    const [credentials, setCredentials] = useState({ username: '', password: '' });
    const [error, setError] = useState('');

    const handleLogin = (e) => {
        e.preventDefault();
        axios.post('http://localhost:8080/api/auth/login', credentials)
            .then(response => {
                onLoginSuccess(response.data); // Předáme data uživatele do App.jsx
                setError('');
            })
            .catch(err => {
                setError('Špatné jméno nebo heslo');
            });
    };

    return (
        <div className="card shadow-sm mx-auto" style={{maxWidth: '400px'}}>
            <div className="card-body">
                <h3 className="card-title text-center mb-4">Přihlášení</h3>
                {error && <div className="alert alert-danger">{error}</div>}
                <form onSubmit={handleLogin}>
                    <div className="mb-3">
                        <label className="form-label">Uživatelské jméno</label>
                        <input
                            type="text" className="form-control" required
                            onChange={e => setCredentials({...credentials, username: e.target.value})}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">Heslo</label>
                        <input
                            type="password" className="form-control" required
                            onChange={e => setCredentials({...credentials, password: e.target.value})}
                        />
                    </div>
                    <button type="submit" className="btn btn-primary w-100">Přihlásit se</button>
                </form>
            </div>
        </div>
    );
};

export default Login;

import React, { useState } from 'react';
import axios from 'axios';

const Login = ({ onLoginSuccess }) => {
    const [mode, setMode] = useState('login');
    const [credentials, setCredentials] = useState({ username: '', password: '' });
    const [registerData, setRegisterData] = useState({
        username: '',
        password: '',
        email: '',
        firstName: '',
        lastName: ''
    });
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    const handleLogin = (e) => {
        e.preventDefault();
        setSuccess('');
        axios.post('http://localhost:8080/api/auth/login', credentials)
            .then(response => {
                onLoginSuccess(response.data); // Předáme data uživatele do App.jsx
                setError('');
            })
            .catch(err => {
                setError('Špatné jméno nebo heslo');
            });
    };

    const handleRegister = (e) => {
        e.preventDefault();
        setError('');
        axios.post('http://localhost:8080/api/auth/register', registerData)
            .then(response => {
                setSuccess('Registrace proběhla úspěšně.');
                onLoginSuccess(response.data);
            })
            .catch(err => {
                const message = err.response?.data || 'Registrace se nezdařila.';
                setError(message);
            });
    };

    return (
        <div className="card shadow-sm mx-auto" style={{maxWidth: '400px'}}>
            <div className="card-body">
                <div className="btn-group w-100 mb-3" role="group">
                    <button
                        type="button"
                        className={`btn ${mode === 'login' ? 'btn-primary' : 'btn-outline-primary'}`}
                        onClick={() => { setMode('login'); setError(''); setSuccess(''); }}
                    >
                        Přihlášení
                    </button>
                    <button
                        type="button"
                        className={`btn ${mode === 'register' ? 'btn-primary' : 'btn-outline-primary'}`}
                        onClick={() => { setMode('register'); setError(''); setSuccess(''); }}
                    >
                        Registrace
                    </button>
                </div>
                <h3 className="card-title text-center mb-4">
                    {mode === 'login' ? 'Přihlášení' : 'Registrace'}
                </h3>
                {error && <div className="alert alert-danger">{error}</div>}
                {success && <div className="alert alert-success">{success}</div>}

                {mode === 'login' ? (
                    <form onSubmit={handleLogin}>
                        <div className="mb-3">
                            <label className="form-label">Uživatelské jméno</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setCredentials({...credentials, username: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Heslo</label>
                            <input
                                type="password" className="form-control" required
                                onChange={e => setCredentials({...credentials, password: e.target.value})}
                            />
                        </div>
                        <button type="submit" className="btn btn-primary w-100">Přihlásit se</button>
                    </form>
                ) : (
                    <form onSubmit={handleRegister}>
                        <div className="mb-3">
                            <label className="form-label">Uživatelské jméno</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setRegisterData({...registerData, username: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">E-mail</label>
                            <input
                                type="email" className="form-control" required
                                onChange={e => setRegisterData({...registerData, email: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Heslo</label>
                            <input
                                type="password" className="form-control" required
                                onChange={e => setRegisterData({...registerData, password: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Jméno</label>
                            <input
                                type="text" className="form-control"
                                onChange={e => setRegisterData({...registerData, firstName: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Příjmení</label>
                            <input
                                type="text" className="form-control"
                                onChange={e => setRegisterData({...registerData, lastName: e.target.value})}
                            />
                        </div>
                        <button type="submit" className="btn btn-primary w-100">Zaregistrovat se</button>
                    </form>
                )}
            </div>
        </div>
    );
};

export default Login;
